line = input()
pairs = {")": "(", "]": "[", "}": "{"}
stack = []
ok = True
for ch in line:
    if ch in "([{":
        stack.append(ch)
    elif ch in pairs:
        if not stack or stack.pop() != pairs[ch]:
            ok = False
            break
print("BALANCED" if ok and not stack else "NOT BALANCED")

n = int(input())
primes = []
for value in range(2, n + 1):
    if all(value % p for p in primes if p * p <= value):
        primes.append(value)
print(" ".join(map(str, primes)))

